module mul16 (
    input clk,
    input clr,
    input x,
    input y,
    output p
);
    wire [15:0] leaf;
    reg [15:0] r0;
    reg [4:1] clr_d;
    wire [7:0] s1;
    reg [7:0] r1;
    wire [3:0] s2;
    reg [3:0] r2;
    wire [1:0] s3;
    reg [1:0] r3;
    wire [0:0] s4;
    reg [0:0] r4;

    pp00 leaf0 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[0]));
    pp01 leaf1 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[1]));
    pp02 leaf2 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[2]));
    pp03 leaf3 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[3]));
    pp04 leaf4 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[4]));
    pp05 leaf5 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[5]));
    pp06 leaf6 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[6]));
    pp07 leaf7 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[7]));
    pp08 leaf8 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[8]));
    pp09 leaf9 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[9]));
    pp10 leaf10 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[10]));
    pp11 leaf11 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[11]));
    pp12 leaf12 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[12]));
    pp13 leaf13 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[13]));
    pp14 leaf14 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[14]));
    pp15 leaf15 (.clk(clk), .rst(clr), .x0(x), .x1(y), .y31(leaf[15]));

    serial_add add1_0 (.clk(clk), .rst(clr_d[1]), .x0(r0[0]), .x1(r0[1]), .y4(s1[0]));
    serial_add add1_1 (.clk(clk), .rst(clr_d[1]), .x0(r0[2]), .x1(r0[3]), .y4(s1[1]));
    serial_add add1_2 (.clk(clk), .rst(clr_d[1]), .x0(r0[4]), .x1(r0[5]), .y4(s1[2]));
    serial_add add1_3 (.clk(clk), .rst(clr_d[1]), .x0(r0[6]), .x1(r0[7]), .y4(s1[3]));
    serial_add add1_4 (.clk(clk), .rst(clr_d[1]), .x0(r0[8]), .x1(r0[9]), .y4(s1[4]));
    serial_add add1_5 (.clk(clk), .rst(clr_d[1]), .x0(r0[10]), .x1(r0[11]), .y4(s1[5]));
    serial_add add1_6 (.clk(clk), .rst(clr_d[1]), .x0(r0[12]), .x1(r0[13]), .y4(s1[6]));
    serial_add add1_7 (.clk(clk), .rst(clr_d[1]), .x0(r0[14]), .x1(r0[15]), .y4(s1[7]));

    serial_add add2_0 (.clk(clk), .rst(clr_d[2]), .x0(r1[0]), .x1(r1[1]), .y4(s2[0]));
    serial_add add2_1 (.clk(clk), .rst(clr_d[2]), .x0(r1[2]), .x1(r1[3]), .y4(s2[1]));
    serial_add add2_2 (.clk(clk), .rst(clr_d[2]), .x0(r1[4]), .x1(r1[5]), .y4(s2[2]));
    serial_add add2_3 (.clk(clk), .rst(clr_d[2]), .x0(r1[6]), .x1(r1[7]), .y4(s2[3]));

    serial_add add3_0 (.clk(clk), .rst(clr_d[3]), .x0(r2[0]), .x1(r2[1]), .y4(s3[0]));
    serial_add add3_1 (.clk(clk), .rst(clr_d[3]), .x0(r2[2]), .x1(r2[3]), .y4(s3[1]));

    serial_add add4_0 (.clk(clk), .rst(clr_d[4]), .x0(r3[0]), .x1(r3[1]), .y4(s4[0]));

    assign p = r4[0];

    always @(posedge clk) begin
        clr_d <= {clr_d[3:1], clr};
        r0 <= leaf;
        r1 <= s1;
        r2 <= s2;
        r3 <= s3;
        r4 <= s4;
    end
endmodule
